<script setup lang="ts">
import {watch,ref,shallowRef} from 'vue';
import {unifiedWorkspace} from '../services';
import type {Output} from '../../shared/protocol/registry';
import UiIcon from '../components/UiIcon.vue';
const props=defineProps<{deckId:string;deckName:string;deckPath?:string}>();
const emit=defineEmits<{navigate:[page:'cards'|'planner'|'knowledge'|'analysis'];study:[];resume:[sessionId:string];create:[];view:[cardId:string]}>();
const data=shallowRef<Output<'workspace.dashboard'>>(),analysis=shallowRef<Output<'workspace.analytics'>>(),error=ref(''),loading=ref(false);
let request=0;
async function load(){const current=++request;const deckId=props.deckId;error.value='';loading.value=true;data.value=undefined;analysis.value=undefined;try{const [dashboard,stats]=await Promise.all([unifiedWorkspace.dashboard({deckId}),unifiedWorkspace.analytics({deckId,date:{range:'30'},limit:1})]);if(current===request){data.value=dashboard;analysis.value=stats;}}catch(e){if(current===request)error.value=String(e);}finally{if(current===request)loading.value=false;}}
watch(()=>props.deckId,load,{immediate:true});
</script>
<template><section class="r2-deck" aria-label="卡片集概览" :aria-busy="loading">
 <div class="page-heading"><div><h1>{{deckName}}</h1><p>{{deckPath??deckName}} · 记忆、错题与知识积累</p></div><div class="heading-actions"><button class="button" @click="emit('create')"><UiIcon name="add"/>新建卡片</button><button class="button primary" :disabled="!data||!data.cardCount" @click="emit('study')"><UiIcon name="play"/>开始本集复盘</button></div></div>
 <p v-if="error" role="alert">{{error}}<button class="button" @click="load">重新读取概览</button></p>
 <div class="deck-statline"><span><strong>{{data?.cardCount??'—'}}</strong> 张卡片</span><span><strong>{{data?.dueCount??'—'}}</strong> 张待复盘</span><span><strong>{{data?.knowledgeCount??'—'}}</strong> 个知识点</span><span>累计复盘 <strong>{{data?.eventCount??'—'}}</strong> 次</span></div>
 <div class="hero-panel"><div><span class="eyebrow">本集学习计划</span><h2>{{data?!data.cardCount?'还没有卡片，开始积累新知识':data.dueCount?'今天有 '+data.dueCount+' 张卡片需要复盘':'今天的复盘已完成，继续积累新知识':'正在读取学习计划…'}}</h2><p>学习进度和统计按照当前卡片集独立计算。</p></div><button class="button primary" :disabled="!data||!data.cardCount" @click="data?.sessions[0]?emit('resume',data.sessions[0].sessionId):emit('study')"><UiIcon name="play"/>{{data?.sessions.length?'继续学习':'开始复盘'}}</button></div>
 <div class="quick-row"><button v-for="item in [{page:'cards',label:'所有卡片',icon:'cards'},{page:'planner',label:'筛选学习',icon:'search'},{page:'knowledge',label:'知识图谱',icon:'knowledge'},{page:'analysis',label:'学习分析',icon:'insights'}] as const" :key="item.page" :aria-label="'进入'+item.label" class="quick-tile" @click="emit('navigate',item.page)"><UiIcon :name="item.icon"/><span>{{item.label}}</span><UiIcon class="quick-arrow" name="chevron" :size="13"/></button></div>
 <div class="subsection-grid"><section class="surface padded" aria-label="最近卡片"><div class="section-heading"><h2>最近卡片</h2><button class="text-button" @click="emit('navigate','cards')">查看全部 →</button></div><div v-for="c in data?.recentCards.slice(0,4)" :key="c.cardId" class="mini-row"><span class="deck-icon blue compact-icon"><UiIcon name="cards"/></span><div class="mini-row-main no-overflow"><strong class="truncate">{{c.title||'未命名卡片'}}</strong><small>{{c.knowledgeNames.join(' · ')||'尚未关联知识点'}} · {{{question:'单选错题',qa:'问答记忆',direct:'直接记忆'}[c.mode]}}</small></div><span class="mini-row-end">{{c.reviewCount}} 次复盘</span><button class="icon-button" :aria-label="'查看卡片 '+c.title" @click="emit('view',c.cardId)"><UiIcon name="chevron"/></button></div><div v-if="data&&!data.recentCards.length" class="empty-state"><strong>把值得回顾的内容，留在这里</strong>新建卡片，或从卡片列表导入已有内容。</div></section>
 <section class="surface padded" aria-label="复盘概况"><div class="section-heading"><h2>复盘概况</h2><span class="tiny-meta">近 30 天</span></div><div class="metric review-overview-metric"><div class="label">平均自评 · 近 30 天</div><div class="number">{{!analysis?'—':analysis.averageScoreTenths==null?'待评估':(analysis.averageScoreTenths/10).toFixed(1)}} <small v-if="analysis?.averageScoreTenths!=null">/ 10</small></div></div><div class="progress-line" role="meter" aria-label="近30天平均自评" :aria-valuenow="analysis?.averageScoreTenths??undefined" aria-valuemin="0" aria-valuemax="100"><span :style="{width:(analysis?.averageScoreTenths??0)+'%'}"/></div><div class="mini-row"><span class="mini-row-main"><strong>今日完成</strong><small>{{data?.timeZone??'学习时区'}}</small></span><span>{{data?.todayCount??'—'}} 次</span></div><div class="mini-row"><span class="mini-row-main"><strong>单选正确率</strong><small>仅统计有客观结果的复盘</small></span><span>{{data?.objectiveCount?Math.round(data.correctCount/data.objectiveCount*100)+'%':'未记录'}}</span></div><button class="button small" @click="emit('navigate','analysis')">查看完整分析 →</button></section></div>
</section></template>
